module pe_1_1_blk_run_core_core_fsm (
  clk, rst, core_wen, fsm_output, for_for_C_0_tr0, for_for_C_0_tr1, l_S_dq0i_0_dq0i_C_0_tr0,
      l_S_gb_1_gb_C_0_tr0
);
  input clk;
  input rst;
  input core_wen;
  output [7:0] fsm_output;
  reg [7:0] fsm_output;
  input for_for_C_0_tr0;
  input for_for_C_0_tr1;
  input l_S_dq0i_0_dq0i_C_0_tr0;
  input l_S_gb_1_gb_C_0_tr0;


  // FSM State Type Declaration for pe_1_1_blk_run_core_core_fsm_1
  parameter
    main_C_0 = 3'd0,
    for_for_C_0 = 3'd1,
    for_C_0 = 3'd2,
    main_C_1 = 3'd3,
    main_C_2 = 3'd4,
    main_C_3 = 3'd5,
    l_S_dq0i_0_dq0i_C_0 = 3'd6,
    l_S_gb_1_gb_C_0 = 3'd7;

  reg [2:0] state_var;
  reg [2:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : pe_1_1_blk_run_core_core_fsm_1
    case (state_var)
      for_for_C_0 : begin
        fsm_output = 8'b00000010;
        if ( for_for_C_0_tr0 ) begin
          state_var_NS = main_C_1;
        end
        else if ( for_for_C_0_tr1 ) begin
          state_var_NS = for_for_C_0;
        end
        else begin
          state_var_NS = for_C_0;
        end
      end
      for_C_0 : begin
        fsm_output = 8'b00000100;
        state_var_NS = for_for_C_0;
      end
      main_C_1 : begin
        fsm_output = 8'b00001000;
        state_var_NS = main_C_2;
      end
      main_C_2 : begin
        fsm_output = 8'b00010000;
        state_var_NS = main_C_3;
      end
      main_C_3 : begin
        fsm_output = 8'b00100000;
        state_var_NS = l_S_dq0i_0_dq0i_C_0;
      end
      l_S_dq0i_0_dq0i_C_0 : begin
        fsm_output = 8'b01000000;
        if ( l_S_dq0i_0_dq0i_C_0_tr0 ) begin
          state_var_NS = l_S_gb_1_gb_C_0;
        end
        else begin
          state_var_NS = l_S_dq0i_0_dq0i_C_0;
        end
      end
      l_S_gb_1_gb_C_0 : begin
        fsm_output = 8'b10000000;
        if ( l_S_gb_1_gb_C_0_tr0 ) begin
          state_var_NS = main_C_0;
        end
        else begin
          state_var_NS = l_S_gb_1_gb_C_0;
        end
      end
      // main_C_0
      default : begin
        fsm_output = 8'b00000001;
        state_var_NS = for_for_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else if ( core_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

