  input l_S_g_0_g640_C_7_tr0;


  // FSM State Type Declaration for rb_merge_0_blk_run_core_core_fsm_1
  parameter
    main_C_0 = 4'd0,
    l_S_g_0_g640_C_0 = 4'd1,
    l_S_g_0_g640_C_1 = 4'd2,
    l_S_g_0_g640_C_2 = 4'd3,
    l_S_g_0_g640_C_3 = 4'd4,
    l_S_g_0_g640_C_4 = 4'd5,
    l_S_g_0_g640_C_5 = 4'd6,
    l_S_g_0_g640_C_6 = 4'd7,
    l_S_g_0_g640_C_7 = 4'd8;

  reg [3:0] state_var;
  reg [3:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : rb_merge_0_blk_run_core_core_fsm_1
    case (state_var)
      l_S_g_0_g640_C_0 : begin
        fsm_output = 9'b000000010;
        state_var_NS = l_S_g_0_g640_C_1;
      end
      l_S_g_0_g640_C_1 : begin
        fsm_output = 9'b000000100;
        state_var_NS = l_S_g_0_g640_C_2;
      end
      l_S_g_0_g640_C_2 : begin
        fsm_output = 9'b000001000;
        state_var_NS = l_S_g_0_g640_C_3;
      end
      l_S_g_0_g640_C_3 : begin
        fsm_output = 9'b000010000;
        state_var_NS = l_S_g_0_g640_C_4;
      end
      l_S_g_0_g640_C_4 : begin
        fsm_output = 9'b000100000;
        state_var_NS = l_S_g_0_g640_C_5;
      end
      l_S_g_0_g640_C_5 : begin
        fsm_output = 9'b001000000;
        state_var_NS = l_S_g_0_g640_C_6;
      end
      l_S_g_0_g640_C_6 : begin
        fsm_output = 9'b010000000;
        state_var_NS = l_S_g_0_g640_C_7;
      end
      l_S_g_0_g640_C_7 : begin
        fsm_output = 9'b100000000;
        if ( l_S_g_0_g640_C_7_tr0 ) begin
          state_var_NS = main_C_0;
        end
        else begin
          state_var_NS = l_S_g_0_g640_C_0;
        end
      end
      // main_C_0
      default : begin
        fsm_output = 9'b000000001;
        state_var_NS = l_S_g_0_g640_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else if ( core_wen ) begin
      state_var <= state_var_NS;
    end
  end

