module rborder_0_blk_run_core_core_fsm (
  clk, rst, core_wen, fsm_output, for_C_0_tr0, l_S_bt_1_bt_C_0_tr0, l_S_dq4_2_dq4_C_0_tr0
);
  input clk;
  input rst;
  input core_wen;
  output [4:0] fsm_output;
  reg [4:0] fsm_output;
  input for_C_0_tr0;
  input l_S_bt_1_bt_C_0_tr0;
  input l_S_dq4_2_dq4_C_0_tr0;


  // FSM State Type Declaration for rborder_0_blk_run_core_core_fsm_1
  parameter
    main_C_0 = 3'd0,
    for_C_0 = 3'd1,
    l_S_bt_1_bt_C_0 = 3'd2,
    main_C_1 = 3'd3,
    l_S_dq4_2_dq4_C_0 = 3'd4;

  reg [2:0] state_var;
  reg [2:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : rborder_0_blk_run_core_core_fsm_1
    case (state_var)
      for_C_0 : begin
        fsm_output = 5'b00010;
        if ( for_C_0_tr0 ) begin
          state_var_NS = l_S_bt_1_bt_C_0;
        end
        else begin
          state_var_NS = for_C_0;
        end
      end
      l_S_bt_1_bt_C_0 : begin
        fsm_output = 5'b00100;
        if ( l_S_bt_1_bt_C_0_tr0 ) begin
          state_var_NS = main_C_1;
        end
        else begin
          state_var_NS = l_S_bt_1_bt_C_0;
        end
      end
      main_C_1 : begin
        fsm_output = 5'b01000;
        state_var_NS = l_S_dq4_2_dq4_C_0;
      end
      l_S_dq4_2_dq4_C_0 : begin
        fsm_output = 5'b10000;
        if ( l_S_dq4_2_dq4_C_0_tr0 ) begin
          state_var_NS = main_C_0;
        end
        else begin
          state_var_NS = l_S_dq4_2_dq4_C_0;
        end
      end
      // main_C_0
      default : begin
        fsm_output = 5'b00001;
        state_var_NS = for_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else if ( core_wen ) begin
      state_var <= state_var_NS;
    end
  end

endmodule

